def hat_closed():
    t = t_of(0.09)
    return norm(highpass(rng.standard_normal(len(t)), 6500) * np.exp(-t / 0.014), 0.8)

def hat_open():
    t = t_of(0.45)
    return norm(highpass(rng.standard_normal(len(t)), 6500) * np.exp(-t / 0.11), 0.8)

def riser():
    T = 2.0
    t = t_of(T)
    x = rng.standard_normal(len(t))
    # one-pole low-pass with cutoff sweeping exponentially 250 Hz -> 9 kHz
    fc = 250 * (9000 / 250) ** (t / T)
    a = 1 - np.exp(-2 * np.pi * fc / SR)
    y = np.empty_like(x)
    acc = 0.0
    for i in range(len(x)):
        acc += a[i] * (x[i] - acc)
        y[i] = acc
    env = (t / T) ** 2.2
    return norm(y * env, 0.8)

def crash():
    t = t_of(1.6)
    x = highpass(rng.standard_normal(len(t)), 2500)
    tone = np.sin(2 * np.pi * 5200 * t) * 0.12
    return norm((x + tone) * np.exp(-t / 0.45) * (1 - np.exp(-t / 0.002)), 0.8)

